"""Build the revised report, preserving the current plain layout."""
from pathlib import Path
import sys
ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / 'reports'))
from word_style import Report
r = Report(14, 'Планирование и осуществление международного расширения стартапа, изучение международных рынков')
r.heading('1. Проект и выбор рынка', 1)
r.paragraph('Команда планирует выйти на рынок Германии через местного продавца или интегратора. Первые покупатели: владельцы Home Assistant и других локальных систем умного дома.', bold=False)
r.heading('Что представляет собой продукт', 2)
r.paragraph('«Ягель A1» показывает время, CO₂, температуру, влажность и давление на экране 2,9″. В приборе установлены ESP32-C3, датчики MH-Z19B и BME280, часы DS3231. Пользователь может открыть схему, прошивку и модель корпуса по лицензии MIT [1].', bold=False)
r.paragraph('Прибор работает без обязательного облака и серверов производителя. Пользователь видит показания на экране и получает их через локальный API. Для этого ему не нужны регистрация в сервисе производителя и подписка.', bold=True)
r.paragraph('Владелец хранит историю и настраивает автоматизации в своей домашней системе. Синхронизацию часов через интернет включает по желанию.', bold=False)
r.heading('Готовность продукта', 2)
r.paragraph('В прошивке реализованы измерения, локальный API и настройка через интерфейс устройства. Владелец меняет параметры без правки кода и перепрошивки. Перед передачей партии команда проверит работу в разных домашних сетях.', bold=False)
r.heading('Почему выбрана Германия (задание № 1)', 2)
r.paragraph('По опросу Bitkom, в 2026 году 52% жителей Германии от 16 лет используют дома устройства Smart Home; в 2024 году их было 46%. Среди пользователей 87% учитывают безопасность данных и приватность, 79% совместимость устройств [2]. Для этой аудитории команда покажет подключение «Ягеля» к домашней системе и работу без интернета.', bold=False)
r.paragraph('Покупатели уже могут выбрать Aranet4 с E-Ink экраном и Bluetooth или открытый AirGradient ONE с локальным подключением к Home Assistant [3, 4]. Команда сравнит «Ягель» с ними по цене, настройке, ремонту и поддержке. Число потенциальных покупателей уточнит на интервью.', bold=False)
r.paragraph('NBS советует перед переговорами подготовить аргументы об общественной пользе продукта [17]. Команда покажет партнёру три примера: проветривание по показаниям CO₂, управление вентиляцией и замену деталей при ремонте.', bold=False)
r.page()
r.heading('2. Польза и адаптация продукта (задание № 2)', 1)
r.heading('Здоровье и условия в помещении', 2)
r.paragraph('Пользователь видит рост CO₂ и выбирает время для проветривания. Umweltbundesamt рекомендует улучшать воздухообмен при превышении 1 000 ppm [14]. В демонстрации команда покажет, как меняются показания в занятой комнате и после проветривания.', bold=False)
r.heading('Энергоэффективность', 2)
r.paragraph('В Home Assistant владелец может управлять совместимой вентиляцией по показаниям CO₂. Umweltbundesamt рекомендует правильное проветривание как часть экономного отопления [15]. В пилоте команда сравнит расход энергии при сходной погоде, занятости комнаты и качестве воздуха.', bold=False)
r.heading('Экология и срок службы', 2)
r.paragraph('Открытые схема и корпус позволяют владельцу разобраться в устройстве и заменить детали. Для ремонта команда подготовит инструкцию и список совместимых компонентов. Основные функции сохранятся после закрытия сервиса производителя. Более долгий срок использования электроники помогает беречь ресурсы [16].', bold=False)
r.heading('Подготовка к продаже', 2)
r.paragraph('Команда переведёт инструкцию и страницы настройки на немецкий язык. Проверит 24-часовой формат и часовой пояс Германии с переходом на летнее время. На экране оставит °C, %, hPa и ppm.', bold=False)
r.paragraph('Партнёр проведёт демонстрации и ответит на вопросы покупателей на немецком. Он организует доставку, возвраты и первую линию поддержки. Команда займётся прошивкой и сложными обращениями. Инструкции разместит на сайте для скачивания.', bold=False)
r.heading('Цена', 2)
r.paragraph('Для интервью команда предложит цену 129 € с НДС, без подписки. При ставке НДС 19% продавец получит 108,40 € до оплаты расходов [5]. Из этой суммы нужно оплатить производство, доставку, долю партнёра, возвраты и поддержку. Руководитель уточнит цену после расчёта затрат и интервью.', bold=False)
r.page()
r.heading('3. План выхода и риски (задание № 3)', 1)
r.paragraph('Команда заключит договор с немецким продавцом или интегратором. Она отвечает за устройство и прошивку, партнёр за продажи, доставку и обслуживание на месте. В договоре стороны закрепят обязанности импортёра. План запуска рассчитан на шесть месяцев.', bold=False)
r.heading('Этапы запуска', 2)
r.paragraph('1. Месяц 1: проверка поставок. Руководитель вместе с партнёром определит таможенный код и происхождение товара. Проверит ограничения на поставку, расчёты и перевозку, получит заключение по сделке. Наличие партнёра в Германии не отменяет санкционных запретов [6].', bold=False)
r.paragraph('2. Месяцы 1–2: проверка спроса. Команда проведёт 15 интервью, обсудит цену 129 € и соберёт не менее 10 заявок на пилот без оплаты. Для переговоров подготовит описание ремонта, локальной работы и плана проверки энергосбережения [17].', bold=False)
r.paragraph('3. Месяцы 2–4: подготовка партии. Разработчик проверит локальные функции, команда переведёт документацию и исправит крепления корпуса. Сверит CO₂ с эталонным прибором и измерит потребление. До выдачи устройств завершит необходимые испытания и регистрации.', bold=False)
r.paragraph('4. Месяцы 4–5: пилот. Партнёр передаст 30 приборов после допуска к продаже. Команда планирует получить не менее 27 подключений по инструкции без помощи разработчика. Проведёт 72-часовой тест без интернета и соберёт отзывы. Расход энергии сравнит при сходных условиях и качестве воздуха.', bold=False)
r.paragraph('5. С месяца 6: расширение продаж. Руководитель изучит возвраты и прибыль с устройства. При положительном результате увеличит партию. Партнёр продолжит демонстрации, работу с сообществами умного дома и техническими обзорами.', bold=False)
r.heading('Правовые условия и риски', 2)
r.paragraph('До продаж команда проверит соответствие требованиям RED и RoHS, подготовит документы и маркировку CE [7, 8]. С партнёром распределит обязанности по электроотходам и упаковке: WEEE/ElektroG и LUCID. Иностранному производителю без присутствия в Германии для WEEE-регистрации нужен местный уполномоченный [9, 10].', bold=False)
r.paragraph('При подготовке прошивки команда учтёт требования RED и CRA к кибербезопасности. Отчётность CRA действует с 11.09.2026, основные обязанности с 11.12.2027 [7, 11]. Продавец организует 14-дневный отказ при дистанционной продаже и исполнение минимум двухлетней законной ответственности за недостатки. Данные заказов и обращений он обработает по GDPR [12, 13].', bold=False)
r.paragraph('Руководитель проверит допустимость поставки до заказа партии. Лабораторные испытания и сравнение с эталонным прибором помогут выявить ошибки показаний. Полная смета покажет, покрывает ли цена затраты. При запрете поставок команда отложит запуск.', bold=False)
r.page()
r.heading('4. Выводы', 1)
r.paragraph('Для первого выхода команда выбрала Германию и работу через местного партнёра. Пилот из 30 устройств позволит проверить настройку, поддержку и цену 129 €. В переговорах команда покажет локальную работу, проветривание по CO₂ и возможность ремонта.', bold=False)
r.paragraph('Руководитель примет решение о следующей партии после испытаний, интервью и расчёта прибыли с прибора. Проверку энергосбережения команда проведёт в пилоте.', bold=False)
r.heading('5. Источники', 1)
r.source(1, 'Проект eink-environment-clock. Схема, прошивка, корпус и лицензия MIT.', 'https://github.com/NKTKLN/eink-environment-clock')
