r.source(12, 'Your Europe. Consumer guarantees, warranties, claims and returns. Правила дистанционной продажи и ответственность за недостатки.', 'https://europa.eu/youreurope/business/selling-in-eu/consumer-contracts-guarantees/consumer-guarantees/index_en.htm')
r.source(13, 'Еврокомиссия. Application of the GDPR. Применимость к обработке персональных данных.', 'https://commission.europa.eu/law/law-topic/data-protection/information-business-and-organisations/application-gdpr_en')
r.source(14, 'Umweltbundesamt. Richtig Lüften in Schulen. CO₂ как показатель вентиляции, рекомендации по проветриванию.', 'https://www.umweltbundesamt.de/richtig-lueften-in-schulen')
r.source(15, 'Umweltbundesamt. Richtiges Heizen schützt das Klima und den Geldbeutel. Отопление, проветривание и энергосбережение.', 'https://www.umweltbundesamt.de/umwelttipps-fuer-den-alltag/richtiges-heizen-schuetzt-das-klima-den-geldbeutel')
r.source(16, 'Umweltbundesamt. Verlängerung der Produktnutzungsdauer. 2020. Срок службы электроники и сохранение ресурсов.', 'https://www.umweltbundesamt.de/publikationen/verlaengerung-der-produktnutzungsdauer')
r.source(17, 'NBS. Немецкий рынок: где вход? 15.06.2019. Подготовка аргументов для переговоров.', 'https://nbs-research.com/business/marketing/немецкий-рынок-где-вход')
